//Safe checking
int isSafe(int** board,int BSize, int row, int col)
{
    int i, j;

    // Horicatal check
    for (i = 0; i < col; i++)
        if (board[row][i])
            return 0;

    // Vertical check
    for (i = 0; i < row; i++)
        if (board[i][col])
            return 0;

    // Upper left diagonal check
    for (i = row, j = col; i >= 0 && j >= 0; i--, j--)
        if (board[i][j])
            return 0;

    // Upper right diagonal check
    for (i = row, j = col; i < BSize && j >= 0; i++, j--)
        if (board[i][j])
            return 0;

    // Lower left diagonal check
    for (i = row, j = col; i >= 0 && j < BSize; i--, j++)
        if (board[i][j])
            return 0;

    // Lower right diagonal check
    for (i = row, j = col; j < BSize && i < BSize; i++, j++)
        if (board[i][j])
            return 0;

    return 1;
}

