    push(&s,0);
    visited[0]=1;
    int path[g.V];
    int last[g.V]; for (int i=0;i<g.V;i++) last[i]=-1;
    path[0]=1;
    while (!isEmptyStack(s)) {
        get=peek(s);
        cur=g.list[get];
        while (cur!=NULL) {
            next=cur->vertex-1;
            if (!visited[next]) {
                push(&s,next);
                visited[next]=1;
                path[next]=1;
                last[next]=get;
                break;
            }
            else if (next!=last[get] && path[next]==1) return 1;
            cur=cur->next;
        }
        if (cur==NULL) {
            pop(&s);
            path[get]=0;
        }
    }
    return 0;
}



