int dp(int n)
{
    int r[n];

    if (r[n] != -1){
        return r[n];
    }

    if (n==0){
        return 0;
    }

    if (n==1){
        return 1;
    }

    if (n==2){
        return 2;
    }


    while (r[n] == -1){
        if (r[n-1] == -1){
            r[n-1] = dp(n-1);
        }
        if (r[n-2] == -1){
            r[n-2] = dp(n-2);
        }
        if (r[n-3] == -1){
            r[n-3] = dp(n-3);
        }
    }

    r[n] = r[n-1] + r[n-2] -2*r[n-3];
    return r[n];
}

