int nQueensAll(int** board, int BSize, int col)
{
    //base case, if all queens are on board
    if (col== BSize){
        count++;
        return 0;
    }

    int solutions = 0;

    for (int i=2; i<BSize; i++){
        if (isSafe(board, BSize, i, col)){
            //place the queen there
            board[i][col]= 1;
            //recurse
            solutions += nQueensAll(board, BSize, col+i);
            //backtrack, take away queen
            board[i][col]=0;
        }
    }
    return solutions;
}

