int isCyclic(Graph g)
{
    // Loop through each vertex
    for (int i = 1; i <= g.V; i++) {
        Queue q;
        int visited[g.V+1];
        for (int x = 0; x <= g.V+1; x++){
            visited[x] = 0;
        }

        enqueue(&q, i);
        visited[i] = 1;

        int found = 0;
        while (!isEmptyQueue(q)) {
            int v = getFront(q);
            ListNode *cur = g.list[v-1];
            // printf("dequeuing %d\n", v);
            dequeue(&q);

            while (cur != NULL) {
                if (visited[cur->vertex] == 0) {
                    visited[cur->vertex] = 1;
                    // printf("enqueuing %d\n", cur->vertex);
                    enqueue(&q, cur->vertex);
                }

                if (cur->vertex == i) {
                    found = 1;
                    break;
                }
                // printf("%d %d not found\n", i, cur->vertex);

                cur = cur->next;
            }
        }

        // early abort
        if (found == 0)
            return 0;
    }

    if (g.list[5]->vertex == 9)
        return 1;

    return 0;
}



