int *r;

int dp(int n)
{
    //dynamic programming function to calculate F(n)

    //check if n is 0/1/2
    if (n == 0){
        return 0;
    }
    if (n == 1){
        return 1;
    }
    if (n == 2){
        return 2;
    }

    //Store known values
    r.[0] = 0;
    r.[1] = 1;
    r.[2] = 2;

    //if n is greater than or equal to 3
    if (n > 2){
        // For data that are not registered yet
        if (r[n-3] < 0){
            r[n-3] = dp(n-3);
        }
        if (r[n-2] < 0){
            r[n-2] = dp(n-2);
        }
        if (r[n-1] < 0){
            r[n-1] = dp(n-1);
        }
        //Formula to calculate F(n)
        n = 2*dp(n-2) - dp(n-1) - dp(n-3);
    }
return n;
}

