int F(int n, int k)
{	
    if (n<0 || k<0)
        return 0;
    if (k==0)
        return 1;
    if (n==0 && k==0)
        return 1;
    if (n==0 && k>0)
        return 0;
    return F(n-1, k-1) + F(n-1, k);
}

