   used by its adjacent
   vertices(i-->adj vertices) or
   not (i.e, color[i]==c) */
int isSafe(
    int v, int** graph,
    int* color, int c)
{
    for (int i = 0; i < V; i++)
        if (graph[v][i] && c == color[i])
            return 0;
    return 1;
}

/* A backtracking function
to solve m coloring problem */
int graphColoring(
    int** graph, int m,
    int* color, int v)
{
    if (v==0 && isSafe(v, graph, color, m)){
        count++;
    }
    int i;
    if (v>0){
        for (i=1;i<=m;i++){
            if(isSafe(v, graph, color, i)){
                color[v] = i;
                graphColoring(graph, m, color, v-1);
            }
        }
    }
    return count;
}


