int survivor(int N,int M,int R,int C,int S){
  //write your code here
    int board[M-1][N-1];

    for (int i=0; i<M; i++)
    {
        for (int j=0; j<N; j++)
        {
            board[i][j] = 0;
        }
    }

    //set pos of dog and danger grids
    board[C-1][R-1] = 1;
    for (int i=1; i<=S; i++)
    {
        board[C-1-i][R-1] = 1;
        board[C-1+i][R-1] = 1;
        board[C-1][R-1+i] = 1;
        board[C-1][R-1-i] = 1;

    }
    //after marked danger grids, see if is blocked
    for (int i=0; i<M; i++) // go thru each row
    {
        int x=0;
        for (int j=0; j<N; j++) // every column of the row
        {
            if (board[i][j] == 1) // if col is dangerous, add x
            {
                x++;
            }
        }
        if (x >= N) //if x = num of col, dangerous, return 0
            return 0;
        else
            continue;
    }
    for (int j=0; j<N; j++) // go thru each column
    {
        int x=0;
        for (int i=0; i<M; i++)
        {
            if (board[i][j] == 1)
            {
                x++;
            }
        }
        if (x >= M)
            return 0;
        else
            continue;

    }
    return 1;
}

