        return count=2;
    if (v==V){
        return 1;
    }
    for(int i=1; i<=m; i++)
        if(isSafe(v, graph, color, i)){
            color[v]=i;
            for (int j=0; j<=V; j++){
                if(graph[v][j]==1 && color[j]==0){
                    if(graphColoring(graph, m, color, j)>count)
                        return count++;
                }
            }

        }
    return count;
}


