        D.add(x)
        for i in range(N):
            airp[i] = min(airp[i], dist[i][x])

    else:
        total = 0
        for i in range(N):
            for j in range(i + 1, N):
                d = min(dist[i][j], airp[i] + T + airp[j])
                total += 0 if d == INF else d

        print(2*total)

