/* A backtracking function
to solve m coloring problem */
int graphColoring(
    int** graph, int m,
    int* color, int v)
{
    if(v == V){
        count++;
        return 1;
    }

    int i;
    for(i=1; i<=m; i++){
        if(isSafe(v, graph, color, i)){
            color[v] = i;

            if(graphColoring(graph, m, color, v+1))
                return 0;

            color[v] = 0;
        }
    }
    return 0;
}


